namespace TicketClassifier.Models;

public class ModelLabels
{
    public string[] Labels { get; }

    public ModelLabels(string[] labels) => Labels = labels;
}

arguments.new_str:
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");

// Train the model at startup so the latest data is always reflected
var (_, labels) = TicketModelTrainer.Train(dataPath, modelPath,
    LoggerFactory.Create(b => b.AddConsole()).CreateLogger("ModelTrainer"));

builder.Services.AddSingleton(new ModelLabels(labels));
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

